hooks.command:
if (item.classList.contains('menu-item-insert-row-above')) {
    env.api.insertRowAbove(cell.parentNode);
} else if (item.classList.contains('menu-item-insert-row-below')) {
    env.api.insertRowBelow(cell.parentNode);
} else if (item.classList.contains('menu-item-delete-row')) {
    env.api.deleteRow(cell.parentNode);
} else if (item.classList.contains('menu-item-insert-col-left')) {
    env.api.insertColLeft(cell.cellIndex);
} else if (item.classList.contains('menu-item-insert-col-right')) {
    env.api.insertColRight(cell.cellIndex);
} else if (item.classList.contains('menu-item-delete-col')) {
    env.api.deleteCol(cell.cellIndex);
} else if (item.classList.contains('menu-item-select-row')) {
    env.api.selectRow(cell.parentNode);
} else if (item.classList.contains('menu-item-select-col')) {
    env.api.selectCol(cell.cellIndex);
} else if (item.classList.contains('menu-item-sort')) {
    const columnIndex = cell.cellIndex;
    const table = env.table;
    const tbody = table.querySelector('tbody');
    const rows = Array.from(tbody.querySelectorAll('tr'));
    const isAscending = !env.state.sortOrder || env.state.sortOrder[columnIndex] === 'descending';

    rows.sort((rowA, rowB) => {
        const cellA = rowA.cells[columnIndex].textContent;
        const cellB = rowB.cells[columnIndex].textContent;
        return isAscending ? cellA.localeCompare(cellB) : cellB.localeCompare(cellA);
    });

    rows.forEach(row => tbody.appendChild(row));
    env.state.sortOrder = env.state.sortOrder || {};
    env.state.sortOrder[columnIndex] = isAscending ? 'ascending' : 'descending';
}

hooks.select:
// Deselect the currently edited cell if it exists and is not the clicked cell
if (env.state.editedCell && env.state.editedCell !== cell) {
    env.api.deselectCell(env.state.editedCell);
    env.state.editedCell = null;
}

// Select the clicked cell
env.api.selectCell(cell);

// Update the edited cell state if the clicked cell is not already being edited
if (env.state.editedCell !== cell) {
    env.state.editedCell = cell;
}

// Ensure the cell is contenteditable if it is being edited
if (env.state.editedCell) {
    env.state.editedCell.contentEditable = 'true';
    env.state.editedCell.focus();
}

