  env.state.sortColumnIndex = colIndex;
  env.state.sortAscending = isAscending;
}

hooks.select:
// Deselect all cells if Shift is not pressed
if (!event.shiftKey) {
  env.api.deselectAllCells();
}

// Select the clicked cell
env.api.selectCell(cell);

// If Shift is pressed, handle the rectangle selection
if (event.shiftKey) {
  if (!env.state.startCell) {
    env.state.startCell = cell;
  } else {
    env.state.endCell = cell;
    const startRow = env.state.startCell.parentNode.rowIndex;
    const startCol = env.state.startCell.cellIndex;
    const endRow = env.state.endCell.parentNode.rowIndex;
    const endCol = env.state.endCell.cellIndex;
    const minRow = Math.min(startRow, endRow);
    const maxRow = Math.max(startRow, endRow);
    const minCol = Math.min(startCol, endCol);
    const maxCol = Math.max(startCol, endCol);

    // Deselect all cells
    env.api.deselectAllCells();

    // Select the rectangle of cells
    for (let row = minRow; row <= maxRow; row++) {
      for (let col = minCol; col <= maxCol; col++) {
        const cellToSelect = env.table.rows[row].cells[col];
        env.api.selectCell(cellToSelect);
      }
    }

    env.state.startCell = null;
    env.state.endCell = null;
  }
}

// If the cell is being edited, end the edit
if (env.state.editingCell === cell) {
  env.api.endEditCell(cell);
} else {
  // If the cell is not being edited and it's a single click, start editing
  if (!event.detail || event.detail === 1) {
    env.api.editCell(cell);
  }
}

