hooks.command:
if (item.classList.contains('menu-item-insert-row-above')) {
  const newRow = env.table.insertRow(cell.parentNode.rowIndex);
  const cells = cell.parentNode.cells;
  for (let i = 0; i < cells.length; i++) {
    newRow.insertCell(i);
  }
  env.table.tBodies[0].insertBefore(newRow, cell.parentNode);
} else if (item.classList.contains('menu-item-insert-row-below')) {
  const newRow = env.table.insertRow(cell.parentNode.rowIndex + 1);
  const cells = cell.parentNode.cells;
  for (let i = 0; i < cells.length; i++) {
    newRow.insertCell(i);
  }
  if (cell.parentNode.nextSibling) {
    env.table.tBodies[0].insertBefore(newRow, cell.parentNode.nextSibling);
  } else {
    env.table.tBodies[0].appendChild(newRow);
  }
} else if (item.classList.contains('menu-item-delete-row')) {
  env.table.deleteRow(cell.parentNode.rowIndex);
} else if (item.classList.contains('menu-item-insert-col-left')) {
  const colIndex = cell.cellIndex;
  const rows = env.table.rows;
  for (let i = 0; i < rows.length; i++) {
    const newCell = rows[i].insertCell(colIndex);
    if (rows[i].parentNode === env.table.tHead) {
      newCell.textContent = '';
    } else {
      newCell.textContent = rows[i].cells[colIndex] ? rows[i].cells[colIndex].textContent : '';
    }
  }
} else if (item.classList.contains('menu-item-insert-col-right')) {
  const colIndex = cell.cellIndex;
  const rows = env.table.rows;
  for (let i = 0; i < rows.length; i++) {
    const newCell = rows[i].insertCell(colIndex + 1);
    if (rows[i].parentNode === env.table.tHead) {
      newCell.textContent = '';
    } else {
      newCell.textContent = rows[i].cells[colIndex] ? rows[i].cells[colIndex].textContent : '';
    }
  }
} else if (item.classList.contains('menu-item-delete-col')) {
  const colIndex = cell.cellIndex;
  const rows = env.table.rows;
  for (let i = 0; i < rows.length; i++) {
    rows[i].deleteCell(colIndex);
  }
} else if (item.classList.contains('menu-item-select-row')) {
  const row = cell.parentNode;
  const cells = row.cells;
  for (let i = 0; i < cells.length; i++) {
    cells[i].classList.add('selected');
  }
} else if (item.classList.contains('menu-item-select-col')) {
  const colIndex = cell.cellIndex;
  const rows = env.table.rows;
  for (let i = 0; i < rows.length; i++) {
    rows[i].cells[colIndex].classList.add('selected');
  }
} else if (item.classList.contains('menu-item-sort')) {
  const colIndex = cell.cellIndex;
  const rows = Array.from(env.table.tBodies[0].rows);
  const isAscending = env.state.sortAscending === undefined || !env.state.sortAscending;
  rows.sort((a, b) => {
    const textA = a.cells[colIndex].textContent;
    const textB = b.cells[colIndex].textContent;
    return isAscending ? textA.localeCompare(textB) : textB.localeCompare(textA);
  });
  for (let i = 0; i < rows.length; i++) {
    env.table.tBodies[0].appendChild(rows[i]);
  }
  env.state.sortColumnIndex = colIndex;
  env.state.sortAscending = isAscending;
}

