if (item.classList.contains('menu-item-insert-row-above')) {
  const row = cell.parentElement;
  const table = env.table;
  const newRow = row.cloneNode(true);
  row.parentNode.insertBefore(newRow, row);
} else if (item.classList.contains('menu-item-insert-row-below')) {
  const row = cell.parentElement;
  const table = env.table;
  const newRow = row.cloneNode(true);
  row.parentNode.insertBefore(newRow, row.nextSibling);
} else if (item.classList.contains('menu-item-delete-row')) {
  const row = cell.parentElement;
  row.parentNode.removeChild(row);
} else if (item.classList.contains('menu-item-insert-col-left')) {
  const colIndex = Array.from(cell.parentElement.children).indexOf(cell);
  const table = env.table;
  const rows = table.querySelectorAll('tr');
  rows.forEach(row => {
    const newCell = document.createElement('th');
    row.insertBefore(newCell, row.children[colIndex]);
  });
} else if (item.classList.contains('menu-item-insert-col-right')) {
  const colIndex = Array.from(cell.parentElement.children).indexOf(cell);
  const table = env.table;
  const rows = table.querySelectorAll('tr');
  rows.forEach(row => {
    const newCell = document.createElement('th');
    row.insertBefore(newCell, row.children[colIndex + 1]);
  });
} else if (item.classList.contains('menu-item-delete-col')) {
  const colIndex = Array.from(cell.parentElement.children).indexOf(cell);
  const table = env.table;
  const rows = table.querySelectorAll('tr');
  rows.forEach(row => {
    row.removeChild(row.children[colIndex]);
  });
} else if (item.classList.contains('menu-item-select-row')) {
  const row = cell.parentElement;
  const cells = Array.from(row.children);
  cells.forEach(c => c.classList.add('selected'));
} else if (item.classList.contains('menu-item-select-col')) {
  const colIndex = Array.from(cell.parentElement.children).indexOf(cell);
  const table = env.table;
  const rows = table.querySelectorAll('tr');
  rows.forEach(row => {
    const cell = row.children[colIndex];
    if (cell) cell.classList.add('selected');
  });
} else if (item.classList.contains('menu-item-sort')) {
  const colIndex = Array.from(cell.parentElement.children).indexOf(cell);
  const table = env.table;
  const rows = Array.from(table.querySelectorAll('tbody tr'));
  const isAscending = env.state.sortOrder && env.state.sortOrder[colIndex] === 'asc';
  const sortedRows = rows.sort((a, b) => {
    const aValue = a.children[colIndex].textContent;
    const bValue = b.children[colIndex].textContent;
    if (isAscending) {
      return aValue.localeCompare(bValue);
    } else {
      return bValue.localeCompare(aValue);
    }
  });
  const tbody = table.querySelector('tbody');
  sortedRows.forEach(row => tbody.appendChild(row));
  env.state.sortOrder = env.state.sortOrder || {};
  env.state.sortOrder[colIndex] = isAscending ? 'desc' : 'asc';
}

hooks.select:
if (env.state.isEditing) {
  const editableCell = env.state.isEditing;
  if (editableCell === cell) {
    return;
  }
  editableCell.contentEditable = false;
  editableCell.classList.remove('editing');
  env.state.isEditing = null;
}

const isSelected = cell.classList.contains('selected');
const isShiftPressed = event.shiftKey;

if (isShiftPressed && env.state.selectedCell) {
  const selectedCell = env.state.selectedCell;
  const selectedRow = selectedCell.parentElement;
  const currentRow = cell.parentElement;
  const selectedColIndex = Array.from(selectedRow.children).indexOf(selectedCell);
  const currentColIndex = Array.from(currentRow.children).indexOf(cell);

  const startRow = Math.min(Array.from(env.table.querySelectorAll('tr')).indexOf(selectedRow), Array.from(env.table.querySelectorAll('tr')).indexOf(currentRow));
  const endRow = Math.max(Array.from(env.table.querySelectorAll('tr')).indexOf(selectedRow), Array.from(env.table.querySelectorAll('tr')).indexOf(currentRow));
  const startCol = Math.min(selectedColIndex, currentColIndex);
  const endCol = Math.max(selectedColIndex, currentColIndex);

  const rows = env.table.querySelectorAll('tr');
  for (let i = startRow; i <= endRow; i++) {
    const row = rows[i];
    const cells = row.children;
    for (let j = startCol; j <= endCol; j++) {
      const targetCell = cells[j];
      if (targetCell) {
        targetCell.classList.add('selected');
        if (!env.state.selectedCells.includes(targetCell)) {
          env.state.selectedCells.push(targetCell);
        }
      }
    }
  }
} else {
  if (!isSelected) {
    env.api.clearSelectedCells();
    cell.classList.add('selected');
    env.state.selectedCell = cell;
    env.state.selectedCells = [cell];
  } else {
    env.state.selectedCell = cell;
  }
}

if (cell.contentEditable && !isShiftPressed) {
  cell.contentEditable = true;
  cell.classList.add('editing');
  env.state.isEditing = cell;
  cell.focus();
}

hooks.open:
// ---- open handler ---------------------------------------------------------
/*  Arguments:
 *    env   – shared environment (env.table, env.state, env.api)
 *    cell  – the <td> or <th> that was right‑clicked (may be null if click on empty table area)
 *    item  – not used for “open”
 *    event – MouseEvent from the context‑click
 *    menu  – previously created menu element (if any)
 *
 *  Return:
 *    A freshly created <div class="menu"> element (detached). The dispatcher
 *    will insert it into the document and position it according to
 *    env.state.menu.position (set below).
 */

(() => {
    // 1️⃣ Ensure a clean state – hide any previous menu
    if (env.api && typeof env.api.hideMenu === "function") env.api.hideMenu();

    // 2️⃣ Create the container
    const container = document.createElement("div");
    container.className = "menu";
    // absolute positioning, min‑size as required
    Object.assign(container.style, {
        position: "absolute",
        minWidth: "100px",
        minHeight: "100px",
        background: "#fff",
        border: "1px solid #aaa",
        borderRadius: "4px",
        boxShadow: "0 2px 6px rgba(0,0,0,0.2)",
        zIndex: 10000,
        padding: "4px 0",
        fontFamily: "sans-serif",
        fontSize: "14px",
        userSelect: "none",
    });

    // 3️⃣ Helper to create a menu item
    const mkItem = (label, className) => {
        const el = document.createElement("div");
        el.className = `menu-item ${className}`;
        el.textContent = label;
        // basic hover style
        el.style.cssText = `
            padding: 4px 12px;
            cursor: pointer;
        `;
        el.addEventListener("mouseenter", () => el.style.background = "#e0e0e0");
        el.addEventListener("mouseleave", () => el.style.background = "transparent");
        // click handling – forward to the generic menu:select event
        el.addEventListener("click", e => {
            e.stopPropagation();               // prevent the global click‑hide
            if (env.api && typeof env.api.on === "function") {
                // emit a high‑level action; listeners (TableCore, DragAndDrop, …) will act
                env.api.on("menu:select", (action, target) => {}); // placeholder – actual subscription elsewhere
            }
            // direct dispatch: tell the system which action was chosen
            if (env.api && typeof env.api.emit === "function") {
                env.api.emit("menu:select", className, el);
            } else if (env.api && typeof env.api.select === "function") {
                // fallback – some implementations expose a generic “select” method
                env.api.select(className, el);
            }
            // hide after a choice
            if (env.api && typeof env.api.hideMenu === "function") env.api.hideMenu();
        });
        return el;
    };

    // 4️⃣ Build the item list according to the clicked cell type
    if (cell) {
        const isHeader = cell.tagName.toLowerCase() === "th";

        if (isHeader) {
            // column actions
            container.appendChild(mkItem("Insert Col Left",  "menu-item-insert-col-left"));
            container.appendChild(mkItem("Insert Col Right", "menu-item-insert-col-right"));
            container.appendChild(mkItem("Delete Col",       "menu-item-delete-col"));
            container.appendChild(mkItem("Select Col",       "menu-item-select-col"));
            container.appendChild(mkItem("Sort",             "menu-item-sort"));
        } else {
            // row actions
            container.appendChild(mkItem("Insert Row Above", "menu-item-insert-row-above"));
            container.appendChild(mkItem("Insert Row Below", "menu-item-insert-row-below"));
            container.appendChild(mkItem("Delete Row",       "menu-item-delete-row"));
            container.appendChild(mkItem("Select Row",       "menu-item-select-row"));
        }
    } else {
        // click on empty table area – only generic actions (e.g., select‑all)
        container.appendChild(mkItem("Select All", "menu-item-select-all"));
    }

    // 5️⃣ Position the menu at the mouse location (clamp to viewport)
    const { clientX: x, clientY: y } = event;
    const { innerWidth: vw, innerHeight: vh } = window;
    // temporary placement to measure size
    container.style.left = "0px";
    container.style.top  = "0px";
    document.body.appendChild(container);
    const { offsetWidth: w, offsetHeight: h } = container;
    document.body.removeChild(container);

    const posX = Math.min(Math.max(0, x), vw - w);
    const posY = Math.min(Math.max(0, y), vh - h);
    container.style.left = `${posX}px`;
    container.style.top  = `${posY}px`;

    // 6️⃣ Store visibility & position in shared state (optional, but matches env.state spec)
    if (env.state) {
        env.state.menu = env.state.menu || {};
        env.state.menu.visible = true;
        env.state.menu.position = { x: posX, y: posY };
    }

    // 7️⃣ Return the detached element – the dispatcher will insert it
    return container;
})();

hooks.command:
(() => {
    // ---- click handler ---------------------------------------------------------
    // Arguments:
    //   env   – shared environment (env.table, env.state, env.api)
    //   cell  – the <td> or <th> that was originally right‑clicked (may be null)
    //   item  – the menu item that was clicked (or a child of it)
    //   event – MouseEvent from the click on the menu
    //   menu  – the menu DOM element that is currently shown

    // 1️⃣ Resolve the actual menu‑item element (the click may land on a child span)
    let target = item;
    while (target && !target.classList.contains('menu-item')) {
        target = target.parentElement;
    }
    if (!target) return; // not a valid menu item

    // 2️⃣ Determine the action from the class name
    const classMap = {
        'menu-item-insert-row-above':  'insertRowAbove',
        'menu-item-insert-row-below':  'insertRowBelow',
        'menu-item-delete-row':       'deleteRow',
        'menu-item-insert-col-left':  'insertColLeft',
        'menu-item-insert-col-right': 'insertColRight',
        'menu-item-delete-col':       'deleteCol',
        'menu-item-select-row':       'selectRow',
        'menu-item-select-col':       'selectCol',
        'menu-item-select-all':       'selectAll',
        'menu-item-sort':             'sort',
    };
    const actionClass = Array.from(target.classList).find(c => classMap[c]);
    const action = actionClass ? classMap[actionClass] : null;
    if (!action) return;

    // 3️⃣ Helper utilities -------------------------------------------------------
    const getRowIndex = (td) => {
        const tr = td.closest('tr');
        return Array.from(tr.parentNode.children).indexOf(tr);
    };
    const getColIndex = (cell) => {
        // works for both th and td; counts preceding sibling cells
        return Array.from(cell.parentNode.children).indexOf(cell);
    };
    const insertCell = (row, index, isHeader) => {
        const newCell = document.createElement(isHeader ? 'th' : 'td');
        newCell.textContent = '';
        row.insertBefore(newCell, row.children[index] || null);
    };
    const deleteCell = (row, index) => {
        if (row.children[index]) row.removeChild(row.children[index]);
    };
    const sortColumn = (colIdx, descending) => {
        const tbody = env.table.tBodies[0];
        const rowsArray = Array.from(tbody.rows);
        rowsArray.sort((a, b) => {
            const aText = a.cells[colIdx]?.textContent?.trim() ?? '';
            const bText = b.cells[colIdx]?.textContent?.trim() ?? '';
            if (aText < bText) return descending ? 1 : -1;
            if (aText > bText) return descending ? -1 : 1;
            return 0;
        });
        // re‑append in sorted order
        rowsArray.forEach(r => tbody.appendChild(r));
    };

    // 4️⃣ Perform the requested operation ---------------------------------------
    switch (action) {
        case 'insertRowAbove': {
            if (!cell) break;
            const rowIdx = getRowIndex(cell);
            const tbody = env.table.tBodies[0];
            const newRow = tbody.insertRow(rowIdx);
            // create same number of cells as existing rows (use first row as template)
            const colCount = env.table.tHead?.rows[0]?.cells.length ||
                             tbody.rows[0]?.cells.length || 1;
            for (let i = 0; i < colCount; i++) newRow.insertCell(i);
            break;
        }
        case 'insertRowBelow': {
            if (!cell) break;
            const rowIdx = getRowIndex(cell);
            const tbody = env.table.tBodies[0];
            const newRow = tbody.insertRow(rowIdx + 1);
            const colCount = env.table.tHead?.rows[0]?.cells.length ||
                             tbody.rows[0]?.cells.length || 1;
            for (let i = 0; i < colCount; i++) newRow.insertCell(i);
            break;
        }
        case 'deleteRow': {
            if (!cell) break;
            const rowIdx = getRowIndex(cell);
            const tbody = env.table.tBodies[0];
            if (tbody.rows[rowIdx]) tbody.deleteRow(rowIdx);
            break;
        }
        case 'insertColLeft': {
            if (!cell) break;
            const colIdx = getColIndex(cell);
            // header
            const theadRow = env.table.tHead?.rows[0];
            if (theadRow) insertCell(theadRow, colIdx, true);
            // body rows
            Array.from(env.table.tBodies[0].rows).forEach(r => insertCell(r, colIdx, false));
            break;
        }
        case 'insertColRight': {
            if (!cell) break;
            const colIdx = getColIndex(cell) + 1;
            const theadRow = env.table.tHead?.rows[0];
            if (theadRow) insertCell(theadRow, colIdx, true);
            Array.from(env.table.tBodies[0].rows).forEach(r => insertCell(r, colIdx, false));
            break;
        }
        case 'deleteCol': {
            if (!cell) break;
            const colIdx = getColIndex(cell);
            const theadRow = env.table.tHead?.rows[0];
            if (theadRow) deleteCell(theadRow, colIdx);
            Array.from(env.table.tBodies[0].rows).forEach(r => deleteCell(r, colIdx));
            break;
        }
        case 'selectRow': {
            if (!cell) break;
            const row = cell.closest('tr');
            if (!row) break;
            Array.from(row.cells).forEach(c => {
                if (env.api && typeof env.api.selectCell === 'function')
                    env.api.selectCell(c, { additive: true });
            });
            break;
        }
        case 'selectCol': {
            if (!cell) break;
            const colIdx = getColIndex(cell);
            // header cell
            const theadRow = env.table.tHead?.rows[0];
            if (theadRow && theadRow.cells[colIdx]) {
                env.api.selectCell(theadRow.cells[colIdx], { additive: true });
            }
            // body cells
            Array.from(env.table.tBodies[0].rows).forEach(r => {
                if (r.cells[colIdx]) env.api.selectCell(r.cells[colIdx], { additive: true });
            });
            break;
        }
        case 'selectAll': {
            if (env.api && typeof env.api.selectAll === 'function')
                env.api.selectAll();
            break;
        }
        case 'sort': {
            if (!cell) break;
            const colIdx = getColIndex(cell);
            // keep a toggle flag per column in state
            env.state.sort = env.state.sort || {};
            const desc = !(env.state.sort[colIdx] === 'desc'); // first click = desc
            env.state.sort[colIdx] = desc ? 'desc' : 'asc';
            sortColumn(colIdx, desc);
            break;
        }
        default:
            break;
    }

    // 5️⃣ Hide the menu after the action
    if (env.api && typeof env.api.hideMenu === 'function') env.api.hideMenu();
})();

