hooks.select:
(() => {
    // ---- click handler ---------------------------------------------------------
    // Arguments:
    //   env   – shared environment (env.table, env.state, env.api)
    //   cell  – the <td> or <th> that was originally clicked (may be null)
    //   item  – the menu item that was clicked (or a child of it)
    //   event – MouseEvent from the click on the menu
    //   menu  – the menu DOM element that is currently shown

    // 1️⃣ Resolve the actual menu‑item element (click may land on a child)
    let target = item;
    while (target && !target.classList.contains('menu-item')) {
        target = target.parentElement;
    }
    if (!target) return; // not a valid menu item

    // 2️⃣ Map class names to actions
    const actionMap = {
        'menu-item-select-row': 'selectRow',
        'menu-item-select-col': 'selectCol',
        'menu-item-select-all': 'selectAll',
        // future actions can be added here
    };
    const actionClass = Array.from(target.classList).find(c => actionMap[c]);
    const action = actionClass ? actionMap[actionClass] : null;
    if (!action) return;

    // 3️⃣ Helper to add/remove visual class and update shared selection
    const toggleCell = (c, additive) => {
        if (additive) {
            c.classList.add('selected');
            env.state.selection = env.state.selection || new Set();
            env.state.selection.add(c);
        } else {
            c.classList.remove('selected');
            if (env.state.selection) env.state.selection.delete(c);
        }
    };

    // 4️⃣ Perform the requested operation
    if (action === 'selectRow' && cell) {
        const row = cell.closest('tr');
        if (!row) return;
        const additive = event.shiftKey; // extend selection with Shift
        row.querySelectorAll('td,th').forEach(c => toggleCell(c, additive));
    } else if (action === 'selectCol' && cell) {
        const colIdx = Array.from(cell.parentNode.children).indexOf(cell);
        const additive = event.shiftKey;
        // header cell (if any)
        const theadRow = env.table.tHead?.rows[0];
        if (theadRow && theadRow.cells[colIdx]) toggleCell(theadRow.cells[colIdx], additive);
        // body cells
        env.table.tBodies[0].querySelectorAll('tr').forEach(tr => {
            const c = tr.cells[colIdx];
            if (c) toggleCell(c, additive);
        });
    } else if (action === 'selectAll') {
        // clear previous selection first unless Shift is held
        const additive = event.shiftKey;
        if (!additive) {
            env.state.selection = new Set();
            env.table.querySelectorAll('.selected').forEach(c => c.classList.remove('selected'));
        }
        env.table.querySelectorAll('td,th').forEach(c => toggleCell(c, true));
    }

    // 5️⃣ Preserve editing state: if the clicked cell (or any of its children) is
    //     currently being edited, keep it editable after selection changes.
    if (env.state.editingCell && env.state.editingCell.isContentEditable) {
        env.state.editingCell.setAttribute('contenteditable', 'true');
    }

    // 6️⃣ Hide the menu after handling
    if (env.api && typeof env.api.hideMenu === 'function') env.api.hideMenu();
})();

hooks.open:
// ---- open handler ---------------------------------------------------------
// Arguments (available in this scope):
//   env   – shared environment (env.table, env.state)
//   cell  – the <td> or <th> that was right‑clicked (may be null)
//   event – MouseEvent from the context‑click
//   menu  – previously created menu element (if any)
//
// Return the freshly created <div class="menu"> (detached)

{
    // 1️⃣ Hide any previous menu element that might still be in the DOM
    if (menu && menu.parentNode) {
        menu.parentNode.removeChild(menu);
    }

    // 2️⃣ Create the container
    const container = document.createElement('div');
    container.className = 'menu';
    Object.assign(container.style, {
        position: 'absolute',
        minWidth: '100px',
        minHeight: '100px',
        background: '#fff',
        border: '1px solid #aaa',
        borderRadius: '4px',
        boxShadow: '0 2px 6px rgba(0,0,0,0.2)',
        zIndex: 10000,
        padding: '4px 0',
        fontFamily: 'sans-serif',
        fontSize: '14px',
        userSelect: 'none',
    });

    // 3️⃣ Helper to create a menu item
    const mkItem = (label, className) => {
        const el = document.createElement('div');
        el.className = `menu-item ${className}`;
        el.textContent = label;
        el.style.cssText = `
            padding: 4px 12px;
            cursor: pointer;
        `;
        el.addEventListener('mouseenter', () => el.style.background = '#e0e0e0');
        el.addEventListener('mouseleave', () => el.style.background = 'transparent');
        // click handling – hide the menu after a choice
        el.addEventListener('click', e => {
            e.stopPropagation();
            // the dispatcher will listen for the click on the menu item itself,
            // so we just let the event bubble up after hiding.
            if (container && container.parentNode) {
                container.parentNode.removeChild(container);
                if (env.state) {
                    env.state.menu = env.state.menu || {};
                    env.state.menu.visible = false;
                }
            }
        });
        return el;
    };

    // 4️⃣ Build the item list according to the clicked cell
    if (cell) {
        const isHeader = cell.tagName.toLowerCase() === 'th';
        if (isHeader) {
            container.appendChild(mkItem('Insert Col Left',  'menu-item-insert-col-left'));
            container.appendChild(mkItem('Insert Col Right', 'menu-item-insert-col-right'));
            container.appendChild(mkItem('Delete Col',       'menu-item-delete-col'));
            container.appendChild(mkItem('Select Col',       'menu-item-select-col'));
            container.appendChild(mkItem('Sort',             'menu-item-sort'));
        } else {
            container.appendChild(mkItem('Insert Row Above', 'menu-item-insert-row-above'));
            container.appendChild(mkItem('Insert Row Below', 'menu-item-insert-row-below'));
            container.appendChild(mkItem('Delete Row',       'menu-item-delete-row'));
            container.appendChild(mkItem('Select Row',       'menu-item-select-row'));
        }
    } else {
        // click on empty table area – generic action
        container.appendChild(mkItem('Select All', 'menu-item-select-all'));
    }

    // 5️⃣ Position the menu at the mouse location, clamped to viewport
    const { clientX: x, clientY: y } = event;
    const { innerWidth: vw, innerHeight: vh } = window;

    // temporarily add to body to measure size
    container.style.left = '0px';
    container.style.top = '0px';
    document.body.appendChild(container);
    const w = container.offsetWidth;
    const h = container.offsetHeight;
    document.body.removeChild(container);

    const posX = Math.min(Math.max(0, x), vw - w);
    const posY = Math.min(Math.max(0, y), vh - h);
    container.style.left = `${posX}px`;
    container.style.top = `${posY}px`;

    // 6️⃣ Store visibility & position in shared state (optional)
    if (env.state) {
        env.state.menu = env.state.menu || {};
        env.state.menu.visible = true;
        env.state.menu.position = { x: posX, y: posY };
    }

    // 7️⃣ Return the detached menu element; the dispatcher will insert it
    container;
}

hooks.command:
// Resolve the actual menu‑item element (the click may land on a child)
let target = item;
while (target && !target.classList.contains('menu-item')) {
    target = target.parentElement;
}
if (!target) return; // not a valid menu item

// Map class names to logical actions
const classMap = {
    'menu-item-insert-row-above':  'insertRowAbove',
    'menu-item-insert-row-below':  'insertRowBelow',
    'menu-item-delete-row':       'deleteRow',
    'menu-item-insert-col-left':  'insertColLeft',
    'menu-item-insert-col-right': 'insertColRight',
    'menu-item-delete-col':       'deleteCol',
    'menu-item-select-row':       'selectRow',
    'menu-item-select-col':       'selectCol',
    'menu-item-select-all':       'selectAll',
    'menu-item-sort':             'sort',
};
const actionClass = Array.from(target.classList).find(c => classMap[c]);
const action = actionClass ? classMap[actionClass] : null;
if (!action) return;

// Helper utilities
const getRowIndex = td => {
    const tr = td.closest('tr');
    return Array.from(tr.parentNode.children).indexOf(tr);
};
const getColIndex = cell => {
    return Array.from(cell.parentNode.children).indexOf(cell);
};
const insertCell = (row, index, isHeader) => {
    const el = document.createElement(isHeader ? 'th' : 'td');
    el.textContent = '';
    row.insertBefore(el, row.children[index] || null);
};
const deleteCell = (row, index) => {
    if (row.children[index]) row.removeChild(row.children[index]);
};
const sortColumn = (colIdx, descending) => {
    const tbody = env.table.tBodies[0];
    const rows = Array.from(tbody.rows);
    rows.sort((a, b) => {
        const aText = a.cells[colIdx]?.textContent?.trim() ?? '';
        const bText = b.cells[colIdx]?.textContent?.trim() ?? '';
        if (aText < bText) return descending ? 1 : -1;
        if (aText > bText) return descending ? -1 : 1;
        return 0;
    });
    rows.forEach(r => tbody.appendChild(r));
};

// Perform the requested operation
switch (action) {
    case 'insertRowAbove': {
        if (!cell) break;
        const rowIdx = getRowIndex(cell);
        const tbody = env.table.tBodies[0];
        const newRow = tbody.insertRow(rowIdx);
        const colCount = env.table.tHead?.rows[0]?.cells.length ||
                         tbody.rows[0]?.cells.length || 1;
        for (let i = 0; i < colCount; i++) newRow.insertCell(i);
        break;
    }
    case 'insertRowBelow': {
        if (!cell) break;
        const rowIdx = getRowIndex(cell);
        const tbody = env.table.tBodies[0];
        const newRow = tbody.insertRow(rowIdx + 1);
        const colCount = env.table.tHead?.rows[0]?.cells.length ||
                         tbody.rows[0]?.cells.length || 1;
        for (let i = 0; i < colCount; i++) newRow.insertCell(i);
        break;
    }
    case 'deleteRow': {
        if (!cell) break;
        const rowIdx = getRowIndex(cell);
        const tbody = env.table.tBodies[0];
        if (tbody.rows[rowIdx]) tbody.deleteRow(rowIdx);
        break;
    }
    case 'insertColLeft': {
        if (!cell) break;
        const colIdx = getColIndex(cell);
        const theadRow = env.table.tHead?.rows[0];
        if (theadRow) insertCell(theadRow, colIdx, true);
        Array.from(env.table.tBodies[0].rows).forEach(r => insertCell(r, colIdx, false));
        break;
    }
    case 'insertColRight': {
        if (!cell) break;
        const colIdx = getColIndex(cell) + 1;
        const theadRow = env.table.tHead?.rows[0];
        if (theadRow) insertCell(theadRow, colIdx, true);
        Array.from(env.table.tBodies[0].rows).forEach(r => insertCell(r, colIdx, false));
        break;
    }
    case 'deleteCol': {
        if (!cell) break;
        const colIdx = getColIndex(cell);
        const theadRow = env.table.tHead?.rows[0];
        if (theadRow) deleteCell(theadRow, colIdx);
        Array.from(env.table.tBodies[0].rows).forEach(r => deleteCell(r, colIdx));
        break;
    }
    case 'selectRow': {
        if (!cell) break;
        const row = cell.closest('tr');
        if (!row) break;
        row.querySelectorAll('td,th').forEach(c => {
            c.classList.add('selected');
            env.state.selection = env.state.selection || new Set();
            env.state.selection.add(c);
        });
        break;
    }
    case 'selectCol': {
        if (!cell) break;
        const colIdx = getColIndex(cell);
        const theadRow = env.table.tHead?.rows[0];
        if (theadRow && theadRow.cells[colIdx]) {
            theadRow.cells[colIdx].classList.add('selected');
            env.state.selection = env.state.selection || new Set();
            env.state.selection.add(theadRow.cells[colIdx]);
        }
        Array.from(env.table.tBodies[0].rows).forEach(r => {
            const c = r.cells[colIdx];
            if (c) {
                c.classList.add('selected');
                env.state.selection = env.state.selection || new Set();
                env.state.selection.add(c);
            }
        });
        break;
    }
    case 'selectAll': {
        env.table.querySelectorAll('td,th').forEach(c => {
            c.classList.add('selected');
            env.state.selection = env.state.selection || new Set();
            env.state.selection.add(c);
        });
        break;
    }
    case 'sort': {
        if (!cell) break;
        const colIdx = getColIndex(cell);
        env.state.sort = env.state.sort || {};
        const desc = !(env.state.sort[colIdx] === 'desc'); // first click = desc
        env.state.sort[colIdx] = desc ? 'desc' : 'asc';
        sortColumn(colIdx, desc);
        break;
    }
}

// Hide the menu after the action
if (menu && menu.parentNode) {
    menu.parentNode.removeChild(menu);
}
if (env.state) {
    env.state.menu = env.state.menu || {};
    env.state.menu.visible = false;
}

hooks.dismiss:
if (menu && menu.parentNode) {
    menu.parentNode.removeChild(menu);
}
if (env.state) {
    env.state.menu = env.state.menu || {};
    env.state.menu.visible = false;
}

hooks.select:
(() => {
    // ---- click handler ---------------------------------------------------------
    // Arguments:
    //   env   – shared environment (env.table, env.state, env.api)
    //   cell  – the <td> or <th> that was originally clicked (may be null)
    //   item  – the menu item that was clicked (or a child of it)
    //   event – MouseEvent from the click on the menu
    //   menu  – the menu DOM element that is currently shown

    // 1️⃣ Resolve the actual menu‑item element (click may land on a child)
    let target = item;
    while (target && !target.classList.contains('menu-item')) {
        target = target.parentElement;
    }
    if (!target) return; // not a valid menu item

    // 2️⃣ Map class names to actions
    const actionMap = {
        'menu-item-select-row': 'selectRow',
        'menu-item-select-col': 'selectCol',
        'menu-item-select-all': 'selectAll',
        // future actions can be added here
    };
    const actionClass = Array.from(target.classList).find(c => actionMap[c]);
    const action = actionClass ? actionMap[actionClass] : null;
    if (!action) return;

    // 3️⃣ Helper to add/remove visual class and update shared selection
    const toggleCell = (c, additive) => {
        if (additive) {
            c.classList.add('selected');
            env.state.selection = env.state.selection || new Set();
            env.state.selection.add(c);
        } else {
            c.classList.remove('selected');
            if (env.state.selection) env.state.selection.delete(c);
        }
    };

    // 4️⃣ Perform the requested operation
    if (action === 'selectRow' && cell) {
        const row = cell.closest('tr');
        if (!row) return;
        const additive = event.shiftKey; // extend selection with Shift
        row.querySelectorAll('td,th').forEach(c => toggleCell(c, additive));
    } else if (action === 'selectCol' && cell) {
        const colIdx = Array.from(cell.parentNode.children).indexOf(cell);
        const additive = event.shiftKey;
        // header cell (if any)
        const theadRow = env.table.tHead?.rows[0];
        if (theadRow && theadRow.cells[colIdx]) toggleCell(theadRow.cells[colIdx], additive);
        // body cells
        env.table.tBodies[0].querySelectorAll('tr').forEach(tr => {
            const c = tr.cells[colIdx];
            if (c) toggleCell(c, additive);
        });
    } else if (action === 'selectAll') {
        // clear previous selection first unless Shift is held
        const additive = event.shiftKey;
        if (!additive) {
            env.state.selection = new Set();
            env.table.querySelectorAll('.selected').forEach(c => c.classList.remove('selected'));
        }
        env.table.querySelectorAll('td,th').forEach(c => toggleCell(c, true));
    }

    // 5️⃣ Preserve editing state: if the clicked cell (or any of its children) is
    //     currently being edited, keep it editable after selection changes.
    if (env.state.editingCell && env.state.editingCell.isContentEditable) {
        env.state.editingCell.setAttribute('contenteditable', 'true');
    }

    // 6️⃣ Hide the menu after handling
    if (env.api && typeof env.api.hideMenu === 'function') env.api.hideMenu();
})();

hooks.open:
// Build (or rebuild) the context‑menu and return it.
// This code runs inside the single “open” handler (env,cell,event,menu are provided).

// 1️⃣  Ensure a container exists – reuse the one stored in env.state.menu.element
let root = env.state.menu?.element;
if (root) {
    // clear any previous items
    root.innerHTML = '';
} else {
    root = document.createElement('ul');
    root.className = 'menu';
    // basic styling – the dispatcher will insert the element into the DOM,
    // so we can set the visual rules here once.
    Object.assign(root.style, {
        position: 'absolute',
        minWidth: '100px',
        minHeight: '100px',
        padding: '4px 0',
        margin: 0,
        listStyle: 'none',
        background: '#fff',
        border: '1px solid #aaa',
        boxShadow: '2px 2px 6px rgba(0,0,0,.2)',
        zIndex: 9999,
        cursor: 'default',
    });
    // keep a reference for later hide/show
    env.state.menu = { element: root, targetCell: null };
}

// 2️⃣  Remember which cell triggered the menu (null = generic table space)
env.state.menu.targetCell = cell || null;

// 3️⃣  Helper to create a menu item
const mkItem = (label, className, handler) => {
    const li = document.createElement('li');
    li.textContent = label;
    li.className = className;
    li.style.padding = '4px 12px';
    li.style.userSelect = 'none';
    li.style.whiteSpace = 'nowrap';
    li.addEventListener('mouseenter', () => li.style.background = '#eef');
    li.addEventListener('mouseleave', () => li.style.background = '');
    li.addEventListener('click', e => {
        e.stopPropagation();               // prevent the global click‑hide handler
        handler(e);
        // after an action the menu should disappear
        env.api.hideMenu();
    });
    return li;
};

// 4️⃣  Populate items according to the clicked cell type
if (cell) {
    const isHeader = cell.tagName.toLowerCase() === 'th';
    const rowIdx = cell.parentElement.rowIndex;          // includes <thead> rows
    const colIdx = cell.cellIndex;

    if (isHeader) {
        // ── column actions ───────────────────────────────────────
        root.append(
            mkItem('Insert Col Left',  'menu-item-insert-col-left',  () => {
                // insert a new <th> before the current one and matching <td> in each body row
                const theadRow = env.table.tHead.rows[0];
                const newTh = document.createElement('th');
                newTh.textContent = '';
                theadRow.insertBefore(newTh, theadRow.cells[colIdx]);

                for (const tr of env.table.tBodies[0].rows) {
                    const newTd = document.createElement('td');
                    newTd.textContent = '';
                    tr.insertBefore(newTd, tr.cells[colIdx]);
                }
            }),
            mkItem('Insert Col Right', 'menu-item-insert-col-right', () => {
                const theadRow = env.table.tHead.rows[0];
                const newTh = document.createElement('th');
                newTh.textContent = '';
                theadRow.insertBefore(newTh, theadRow.cells[colIdx].nextSibling);

                for (const tr of env.table.tBodies[0].rows) {
                    const newTd = document.createElement('td');
                    newTd.textContent = '';
                    tr.insertBefore(newTd, tr.cells[colIdx].nextSibling);
                }
            }),
            mkItem('Delete Col',       'menu-item-delete-col',       () => {
                // remove header cell
                env.table.tHead.rows[0].deleteCell(colIdx);
                // remove matching body cells
                for (const tr of env.table.tBodies[0].rows) {
                    tr.deleteCell(colIdx);
                }
            }),
            mkItem('Select Col',       'menu-item-select-col',       () => {
                env.api.selectCol(colIdx);
            }),
            mkItem('Sort',             'menu-item-sort',            () => {
                // toggle direction: first click = desc, then asc, then back …
                const dirKey = `__sortDir${colIdx}`;
                const prev = env.state.menu?.[dirKey] || 'asc';
                const next = prev === 'asc' ? 'desc' : 'asc';
                env.state.menu[dirKey] = next;
                env.api.sortRows(colIdx, next);
            })
        );
    } else {
        // ── row actions ───────────────────────────────────────────
        root.append(
            mkItem('Insert Row Above', 'menu-item-insert-row-above', () => {
                const tbody = env.table.tBodies[0];
                const refRow = tbody.rows[rowIdx - env.table.tHead.rows.length];
                const newRow = tbody.insertRow(refRow.rowIndex);
                // create the same number of cells as the existing row
                for (let i = 0; i < refRow.cells.length; i++) {
                    const td = document.createElement('td');
                    td.textContent = '';
                    newRow.appendChild(td);
                }
            }),
            mkItem('Insert Row Below', 'menu-item-insert-row-below', () => {
                const tbody = env.table.tBodies[0];
                const refRow = tbody.rows[rowIdx - env.table.tHead.rows.length];
                const newRow = tbody.insertRow(refRow.rowIndex + 1);
                for (let i = 0; i < refRow.cells.length; i++) {
                    const td = document.createElement('td');
                    td.textContent = '';
                    newRow.appendChild(td);
                }
            }),
            mkItem('Delete Row',       'menu-item-delete-row',       () => {
                const tbody = env.table.tBodies[0];
                const realIdx = rowIdx - env.table.tHead.rows.length;
                if (realIdx >= 0) tbody.deleteRow(realIdx);
            }),
            mkItem('Select Row',       'menu-item-select-row',       () => {
                const realIdx = rowIdx - env.table.tHead.rows.length;
                env.api.selectRow(realIdx);
            })
        );
    }
} else {
    // ── generic table space (no specific cell) ───────────────────────
    // currently we only need a placeholder – could add “Add Row” etc.
    root.append(
        mkItem('Insert Row Below', 'menu-item-insert-row-below', () => {
            const tbody = env.table.tBodies[0];
            const newRow = tbody.insertRow();
            const colCount = env.table.tHead ? env.table.tHead.rows[0].cells.length : 1;
            for (let i = 0; i < colCount; i++) {
                const td = document.createElement('td');
                td.textContent = '';
                newRow.appendChild(td);
            }
        })
    );
}

// 5️⃣  Position the menu at the mouse location (keep it inside viewport)
const { clientX: x, clientY: y } = event;
const { innerWidth, innerHeight } = window;
root.style.left = `${Math.min(x, innerWidth - root.offsetWidth - 4)}px`;
root.style.top  = `${Math.min(y, innerHeight - root.offsetHeight - 4)}px`;

// 6️⃣  Return the detached element – the dispatcher will attach it.
root;

hooks.command:
// ---------------------------------------------------------------
// Click‑handler for a menu item (or any of its children)
// ---------------------------------------------------------------
// Arguments supplied by the dispatcher:
//   env   – shared environment (env.table, env.api, env.state)
//   cell  – the cell that originally opened the menu (may be null)
//   item  – the element that was actually clicked inside the menu
//   event – the original click event
//   menu  – the root <ul> element of the context menu
// ---------------------------------------------------------------

// 1️⃣  Resolve the real menu‑item element (the <li> we created)
let target = item;
while (target && target !== menu && !target.classList.contains('menu-item-insert-row-above')
       && !target.classList.contains('menu-item-insert-row-below')
       && !target.classList.contains('menu-item-delete-row')
       && !target.classList.contains('menu-item-insert-col-left')
       && !target.classList.contains('menu-item-insert-col-right')
       && !target.classList.contains('menu-item-delete-col')
       && !target.classList.contains('menu-item-select-row')
       && !target.classList.contains('menu-item-select-col')
       && !target.classList.contains('menu-item-sort')) {
    target = target.parentElement;
}
if (!target) return;   // not a recognised menu item – nothing to do

// 2️⃣  Helper to get the original cell that opened the menu
const srcCell = env.state.menu?.targetCell || null;
if (!srcCell) return;   // safety – all our actions need a source cell

// 3️⃣  Common indexes
const isHeader = srcCell.tagName.toLowerCase() === 'th';
const rowIdx   = srcCell.parentElement.rowIndex;          // includes <thead> rows
const colIdx   = srcCell.cellIndex;

// 4️⃣  Perform the action based on the item’s class
if (target.classList.contains('menu-item-insert-row-above')) {
    // insert a new <tr> before the current tbody row
    const tbody   = env.table.tBodies[0];
    const realIdx = rowIdx - env.table.tHead?.rows.length; // index inside tbody
    const refRow  = tbody.rows[realIdx];
    const newRow  = tbody.insertRow(refRow.rowIndex);
    for (let i = 0; i < refRow.cells.length; i++) {
        const td = document.createElement('td');
        td.textContent = '';
        newRow.appendChild(td);
    }
}
else if (target.classList.contains('menu-item-insert-row-below')) {
    const tbody   = env.table.tBodies[0];
    const realIdx = rowIdx - env.table.tHead?.rows.length;
    const refRow  = tbody.rows[realIdx];
    const newRow  = tbody.insertRow(refRow.rowIndex + 1);
    for (let i = 0; i < refRow.cells.length; i++) {
        const td = document.createElement('td');
        td.textContent = '';
        newRow.appendChild(td);
    }
}
else if (target.classList.contains('menu-item-delete-row')) {
    const tbody   = env.table.tBodies[0];
    const realIdx = rowIdx - env.table.tHead?.rows.length;
    if (realIdx >= 0) tbody.deleteRow(realIdx);
}
else if (target.classList.contains('menu-item-insert-col-left')) {
    // add a <th> before the current one and matching <td> in every body row
    const theadRow = env.table.tHead.rows[0];
    const newTh    = document.createElement('th');
    newTh.textContent = '';
    theadRow.insertBefore(newTh, theadRow.cells[colIdx]);

    for (const tr of env.table.tBodies[0].rows) {
        const newTd = document.createElement('td');
        newTd.textContent = '';
        tr.insertBefore(newTd, tr.cells[colIdx]);
    }
}
else if (target.classList.contains('menu-item-insert-col-right')) {
    const theadRow = env.table.tHead.rows[0];
    const newTh    = document.createElement('th');
    newTh.textContent = '';
    theadRow.insertBefore(newTh, theadRow.cells[colIdx].nextSibling);

    for (const tr of env.table.tBodies[0].rows) {
        const newTd = document.createElement('td');
        newTd.textContent = '';
        tr.insertBefore(newTd, tr.cells[colIdx].nextSibling);
    }
}
