// 5️⃣  The dispatcher will call env.api.hideMenu() after this handler,
//    so we do not need to hide the menu here.

hooks.dismiss:
// ---------------------------------------------------------------
// “close” handler – invoked when a click occurs outside the menu
// or when a menu item (or any of its children) is activated.
// ---------------------------------------------------------------
// Arguments supplied by the dispatcher:
//   env   – shared environment (env.table, env.api, env.state)
//   cell  – the cell that originally opened the menu (may be null)
//   item  – the element that was actually clicked inside the menu
//   event – the original click event
//   menu  – the root <ul> element of the context menu
// ---------------------------------------------------------------

// The dispatcher already removed the menu element from the DOM
// for us, but we also need to clear our internal state so that a
// subsequent right‑click creates a fresh menu instance.

if (env.state.menu) {
    // clear reference to the DOM element
    env.state.menu.element = null;
    // clear the cell that triggered the menu
    env.state.menu.targetCell = null;
}

// If any temporary data (e.g. sort direction cache) was stored on the
// menu state, wipe it out to avoid leaking stale info.
for (const key of Object.keys(env.state.menu || {})) {
    if (key.startsWith('__sortDir')) delete env.state.menu[key];
}

// Finally, ensure the global hide routine runs (in case the dispatcher
// expects it).  This call is safe even if the menu is already removed.
env.api.hideMenu();

hooks.select:
// ---------------------------------------------------------------
// Click‑handler for a table cell (the main “click” handler)
// ---------------------------------------------------------------
// Arguments supplied by the dispatcher:
//   env   – shared environment (env.table, env.api, env.state)
//   cell  – the <td> or <th> that was clicked
//   item  – the element that was actually clicked inside the menu (unused here)
//   event – the original MouseEvent
//   menu  – the root <ul> element of the context menu (unused here)
// ---------------------------------------------------------------

// 1️⃣  If the click originated from a menu item we ignore it – the
//     “click” handler for the menu will have already processed it.
if (menu && menu.contains(event.target)) {
    // nothing to do, let the menu‑specific handler run
    return;
}

// 2️⃣  Helper to clear any temporary “editing” state if we are about to
//     change the selection.  Editing is kept only when the user clicks
//     the already‑selected cell without modifiers.
const isEditing = !!env.state.editing?.cell;

// 3️⃣  Determine modifier keys
const shift   = event.shiftKey;
const ctrlCmd = event.ctrlKey || event.metaKey;   // Cmd on mac / Ctrl on win

// 4️⃣  If the cell is already selected and no modifier is pressed, we
//     treat the click as a request to edit the cell.
if (!shift && !ctrlCmd && env.state.selection?.cells?.has(cell)) {
    // If we are already editing the same cell, do nothing.
    if (isEditing && env.state.editing.cell === cell) return;

    // Exit any previous edit (commit the change)
    if (isEditing) env.api.exitEdit(true);

    // Enter edit mode for the clicked cell
    env.api.enterEdit(cell);
    return;
}

// 5️⃣  Otherwise we are changing the selection.
//     If we are currently editing a different cell, commit/exit it first.
if (isEditing && env.state.editing.cell !== cell) {
    env.api.exitEdit(true);
}

// 6️⃣  Resolve the selection mode:
//     - Shift  → rectangle/extend selection (anchor stays)
//     - Ctrl   → additive toggle of single cell
//     - none   → single selection (clear previous)
if (shift) {
    // ---- Shift‑click: extend rectangle from the anchor (or start new) ----
    const anchor = env.state.selection?.anchor || cell;   // first cell of the range
    // Update anchor if we didn't have one yet
    if (!env.state.selection?.anchor) {
        env.state.selection.anchor = anchor;
    }
    // Select the rectangular block between anchor and the clicked cell
    env.api.selectRange(anchor, cell);
} else if (ctrlCmd) {
    // ---- Ctrl/Cmd‑click: toggle the clicked cell without affecting others ----
    const already = env.state.selection?.cells?.has(cell);
    if (already) {
        // remove from selection
        cell.classList.remove('selected');
        env.state.selection.cells.delete(cell);
        // if we removed the anchor, clear it (next shift‑click will start a new range)
        if (env.state.selection.anchor === cell) env.state.selection.anchor = null;
    } else {
        // add to selection
        env.api.selectCell(cell, true);   // additive = true
        // keep the first anchor if none exists
        if (!env.state.selection.anchor) env.state.selection.anchor = cell;
    }
} else {
    // ---- Simple click: clear previous selection and select only this cell ----
    env.api.clearSelection();
    env.api.selectCell(cell);
    // set anchor for possible future shift‑selection
    env.state.selection.anchor = cell;
}

// 7️⃣  Ensure the visual class is applied (selectCell/selectRange already do it)
//     but we also guarantee the table element itself has focus for keyboard ops.
env.table.focus?.();

// 8️⃣  If a context‑menu is currently open (e.g. right‑click then left‑click),
//     hide it now because the user performed a normal click.
if (env.state.menu?.element) {
    env.api.hideMenu();
}

hooks.open:
// Build (or rebuild) the context‑menu and return it.
// This code runs inside the single “open” handler (env,cell,event,menu are provided).

// 1️⃣  Ensure a container exists – reuse the one stored in env.state.menu.element
let root = env.state.menu?.element;
if (root) {
    // clear any previous items
    root.innerHTML = '';
} else {
    root = document.createElement('ul');
    root.className = 'menu';
    // basic styling – the dispatcher will insert the element into the DOM,
    // so we can set the visual rules here once.
    Object.assign(root.style, {
        position: 'absolute',
        minWidth: '100px',
        minHeight: '100px',
        padding: '4px 0',
        margin: 0,
        listStyle: 'none',
        background: '#fff',
        border: '1px solid #aaa',
        boxShadow: '2px 2px 6px rgba(0,0,0,.2)',
        zIndex: 9999,
        cursor: 'default',
    });
    // keep a reference for later hide/show
    env.state.menu = { element: root, targetCell: null };
}

// 2️⃣  Remember which cell triggered the menu (null = generic table space)
env.state.menu.targetCell = cell || null;

// 3️⃣  Helper to create a menu item
const mkItem = (label, className, handler) => {
    const li = document.createElement('li');
    li.textContent = label;
    li.className = className;
    li.style.padding = '4px 12px';
    li.style.userSelect = 'none';
    li.style.whiteSpace = 'nowrap';
    li.addEventListener('mouseenter', () => li.style.background = '#eef');
    li.addEventListener('mouseleave', () => li.style.background = '');
    li.addEventListener('click', e => {
        e.stopPropagation();               // prevent the global click‑hide handler
        handler(e);
        // after an action the menu should disappear
        env.api.hideMenu();
    });
    return li;
};

// 4️⃣  Populate items according to the clicked cell type
if (cell) {
    const isHeader = cell.tagName.toLowerCase() === 'th';
    const rowIdx = cell.parentElement.rowIndex;          // includes <thead> rows
    const colIdx = cell.cellIndex;

    if (isHeader) {
        // ── column actions ───────────────────────────────────────
        root.append(
            mkItem('Insert Col Left',  'menu-item-insert-col-left',  () => {
                // insert a new <th> before the current one and matching <td> in each body row
                const theadRow = env.table.tHead.rows[0];
                const newTh = document.createElement('th');
                newTh.textContent = '';
                theadRow.insertBefore(newTh, theadRow.cells[colIdx]);

                for (const tr of env.table.tBodies[0].rows) {
                    const newTd = document.createElement('td');
                    newTd.textContent = '';
                    tr.insertBefore(newTd, tr.cells[colIdx]);
                }
            }),
            mkItem('Insert Col Right', 'menu-item-insert-col-right', () => {
                const theadRow = env.table.tHead.rows[0];
                const newTh = document.createElement('th');
                newTh.textContent = '';
                theadRow.insertBefore(newTh, theadRow.cells[colIdx].nextSibling);

                for (const tr of env.table.tBodies[0].rows) {
                    const newTd = document.createElement('td');
                    newTd.textContent = '';
                    tr.insertBefore(newTd, tr.cells[colIdx].nextSibling);
                }
            }),
            mkItem('Delete Col',       'menu-item-delete-col',       () => {
                // remove header cell
                env.table.tHead.rows[0].deleteCell(colIdx);
                // remove matching body cells
                for (const tr of env.table.tBodies[0].rows) {
                    tr.deleteCell(colIdx);
                }
            }),
            mkItem('Select Col',       'menu-item-select-col',       () => {
                env.api.selectCol(colIdx);
            }),
            mkItem('Sort',             'menu-item-sort',            () => {
                // toggle direction: first click = desc, then asc, then back …
                const dirKey = `__sortDir${colIdx}`;
                const prev = env.state.menu?.[dirKey] || 'asc';
                const next = prev === 'asc' ? 'desc' : 'asc';
                env.state.menu[dirKey] = next;
                env.api.sortRows(colIdx, next);
            })
        );
    } else {
        // ── row actions ───────────────────────────────────────────
        root.append(
            mkItem('Insert Row Above', 'menu-item-insert-row-above', () => {
                const tbody = env.table.tBodies[0];
                const refRow = tbody.rows[rowIdx - env.table.tHead.rows.length];
                const newRow = tbody.insertRow(refRow.rowIndex);
                // create the same number of cells as the existing row
                for (let i = 0; i < refRow.cells.length; i++) {
                    const td = document.createElement('td');
                    td.textContent = '';
                    newRow.appendChild(td);
                }
            }),
            mkItem('Insert Row Below', 'menu-item-insert-row-below', () => {
                const tbody = env.table.tBodies[0];
                const refRow = tbody.rows[rowIdx - env.table.tHead.rows.length];
                const newRow = tbody.insertRow(refRow.rowIndex + 1);
                for (let i = 0; i < refRow.cells.length; i++) {
                    const td = document.createElement('td');
                    td.textContent = '';
                    newRow.appendChild(td);
                }
            }),
            mkItem('Delete Row',       'menu-item-delete-row',       () => {
                const tbody = env.table.tBodies[0];
                const realIdx = rowIdx - env.table.tHead.rows.length;
                if (realIdx >= 0) tbody.deleteRow(realIdx);
            }),
            mkItem('Select Row',       'menu-item-select-row',       () => {
                const realIdx = rowIdx - env.table.tHead.rows.length;
                env.api.selectRow(realIdx);
            })
        );
    }
} else {
    // ── generic table space (no specific cell) ───────────────────────
    // currently we only need a placeholder – could add “Add Row” etc.
    root.append(
        mkItem('Insert Row Below', 'menu-item-insert-row-below', () => {
            const tbody = env.table.tBodies[0];
            const newRow = tbody.insertRow();
            const colCount = env.table.tHead ? env.table.tHead.rows[0].cells.length : 1;
            for (let i = 0; i < colCount; i++) {
                const td = document.createElement('td');
                td.textContent = '';
                newRow.appendChild(td);
            }
        })
    );
}

// 5️⃣  Position the menu at the mouse location (keep it inside viewport)
const { clientX: x, clientY: y } = event;
const { innerWidth, innerHeight } = window;
root.style.left = `${Math.min(x, innerWidth - root.offsetWidth - 4)}px`;
root.style.top  = `${Math.min(y, innerHeight - root.offsetHeight - 4)}px`;

// 6️⃣  Return the detached element – the dispatcher will attach it.
root;

hooks.command:
// ---------------------------------------------------------------
// Click‑handler for a menu item (or any of its children)
// ---------------------------------------------------------------
// Arguments supplied by the dispatcher:
//   env   – shared environment (env.table, env.state)
//   cell  – the cell that originally opened the menu (may be null)
//   item  – the element that was actually clicked inside the menu
//   event – the original click event
//   menu  – the root <ul> element of the context menu
// ---------------------------------------------------------------

// 1️⃣ Resolve the real <li> that represents the menu action
let target = item;
while (target && target !== menu && !target.classList.contains('menu-item-insert-row-above')
       && !target.classList.contains('menu-item-insert-row-below')
       && !target.classList.contains('menu-item-delete-row')
       && !target.classList.contains('menu-item-insert-col-left')
       && !target.classList.contains('menu-item-insert-col-right')
       && !target.classList.contains('menu-item-delete-col')
       && !target.classList.contains('menu-item-select-row')
       && !target.classList.contains('menu-item-select-col')
       && !target.classList.contains('menu-item-sort')) {
    target = target.parentElement;
}
if (!target) return; // not a recognised item

// 2️⃣ Original cell that opened the menu
const srcCell = env.state.menu?.targetCell;
if (!srcCell) return;

// 3️⃣ Common indexes
const isHeader = srcCell.tagName.toLowerCase() === 'th';
const rowIdx   = srcCell.parentElement.rowIndex; // includes <thead> rows
const colIdx   = srcCell.cellIndex;

// 4️⃣ Helper to create a matching number of cells for a new row
const cloneRowStructure = (refRow) => {
    const newRow = refRow.parentElement.insertRow(refRow.rowIndex);
    for (let i = 0; i < refRow.cells.length; i++) {
        const td = document.createElement('td');
        td.textContent = '';
        newRow.appendChild(td);
    }
    return newRow;
};

// 5️⃣ Perform the action based on the class name
if (target.classList.contains('menu-item-insert-row-above')) {
    const tbody = env.table.tBodies[0];
    const realIdx = rowIdx - (env.table.tHead?.rows.length || 0);
    const refRow = tbody.rows[realIdx];
    if (refRow) {
        const newRow = tbody.insertRow(refRow.rowIndex);
        for (let i = 0; i < refRow.cells.length; i++) {
            const td = document.createElement('td');
            td.textContent = '';
            newRow.appendChild(td);
        }
    }
}
else if (target.classList.contains('menu-item-insert-row-below')) {
    const tbody = env.table.tBodies[0];
    const realIdx = rowIdx - (env.table.tHead?.rows.length || 0);
    const refRow = tbody.rows[realIdx];
    if (refRow) {
        const newRow = tbody.insertRow(refRow.rowIndex + 1);
        for (let i = 0; i < refRow.cells.length; i++) {
            const td = document.createElement('td');
            td.textContent = '';
            newRow.appendChild(td);
        }
    }
}
else if (target.classList.contains('menu-item-delete-row')) {
    const tbody = env.table.tBodies[0];
    const realIdx = rowIdx - (env.table.tHead?.rows.length || 0);
    if (realIdx >= 0) tbody.deleteRow(realIdx);
}
else if (target.classList.contains('menu-item-insert-col-left')) {
    // insert <th> before current header cell
    const theadRow = env.table.tHead.rows[0];
    const newTh = document.createElement('th');
    newTh.textContent = '';
    theadRow.insertBefore(newTh, theadRow.cells[colIdx]);

    // insert matching <td> in each body row
    for (const tr of env.table.tBodies[0].rows) {
        const newTd = document.createElement('td');
        newTd.textContent = '';
        tr.insertBefore(newTd, tr.cells[colIdx]);
    }
}
else if (target.classList.contains('menu-item-insert-col-right')) {
    const theadRow = env.table.tHead.rows[0];
    const newTh = document.createElement('th');
    newTh.textContent = '';
    theadRow.insertBefore(newTh, theadRow.cells[colIdx].nextSibling);

    for (const tr of env.table.tBodies[0].rows) {
        const newTd = document.createElement('td');
        newTd.textContent = '';
        tr.insertBefore(newTd, tr.cells[colIdx].nextSibling);
    }
}
else if (target.classList.contains('menu-item-delete-col')) {
    // delete header cell
    env.table.tHead.rows[0].deleteCell(colIdx);
    // delete matching body cells
    for (const tr of env.table.tBodies[0].rows) {
        tr.deleteCell(colIdx);
    }
}
else if (target.classList.contains('menu-item-select-row')) {
    const tbody = env.table.tBodies[0];
    const realIdx = rowIdx - (env.table.tHead?.rows.length || 0);
    const tr = tbody.rows[realIdx];
    if (tr) {
        // clear previous selection
        if (env.state.selection?.cells) {
            env.state.selection.cells.forEach(c => c.classList.remove('selected'));
        }
        // select whole row
        const cells = Array.from(tr.cells);
        cells.forEach(c => c.classList.add('selected'));
        env.state.selection = { cells: new Set(cells), anchor: cells[0] };
    }
}
else if (target.classList.contains('menu-item-select-col')) {
    const colCells = [];
    // header cell
    if (env.table.tHead) colCells.push(env.table.tHead.rows[0].cells[colIdx]);
    // body cells
    for (const tr of env.table.tBodies[0].rows) {
        colCells.push(tr.cells[colIdx]);
    }
    // clear previous selection
    if (env.state.selection?.cells) {
        env.state.selection.cells.forEach(c => c.classList.remove('selected'));
    }
    colCells.forEach(c => c.classList.add('selected'));
    env.state.selection = { cells: new Set(colCells), anchor: colCells[0] };
}
else if (target.classList.contains('menu-item-sort')) {
    // toggle direction (default descending)
    const dirKey = `__sortDir${colIdx}`;
    const prev = env.state.menu?.[dirKey] || 'desc';
    const next = prev === 'desc' ? 'asc' : 'desc';
    env.state.menu[dirKey] = next;

    // gather rows and sort them
    const tbody = env.table.tBodies[0];
    const rowsArray = Array.from(tbody.rows);
    rowsArray.sort((a, b) => {
        const aText = a.cells[colIdx].textContent.trim();
        const bText = b.cells[colIdx].textContent.trim();
        if (aText < bText) return next === 'asc' ? -1 : 1;
        if (aText > bText) return next === 'asc' ? 1 : -1;
        return 0;
    });
    // re‑append in sorted order
    rowsArray.forEach(r => tbody.appendChild(r));
}

// 6️⃣ The dispatcher will hide the menu after this handler, so nothing else is needed.

hooks.dismiss:
// “close” handler – invoked when a click occurs outside the menu
// or when a menu item (or any of its children) is activated.
