// Arguments supplied by the dispatcher:
//   env   – shared environment (env.table, env.state)
//   cell  – the cell that originally opened the menu (may be null)
//   item  – the element that was actually clicked inside the menu
//   event – the original click event
//   menu  – the root <ul> element of the context menu
//
// The dispatcher already removed the menu element from the DOM for us,
// but we must clear our internal state so that a subsequent right‑click
// creates a fresh menu instance.

if (env.state.menu) {
    // clear reference to the DOM element
    env.state.menu.element = null;
    // clear the cell that triggered the menu
    env.state.menu.targetCell = null;
}

// Remove any temporary data (e.g. cached sort direction) stored on the menu state.
for (const key of Object.keys(env.state.menu || {})) {
    if (key.startsWith('__sortDir')) delete env.state.menu[key];
}

// Ensure the menu element is detached from the document (in case the dispatcher
// did not already do it). This also stops it from intercepting pointer events.
if (menu && menu.parentNode) {
    menu.parentNode.removeChild(menu);
}

